export type MessageKey = keyof MessageParams;
export type MessageArguments<K extends MessageKey> = keyof MessageParams[K] extends never
  ? [key: K]
  : [key: K, values: MessageParams[K]];
export type LocalizedMessage = {
  [K in MessageKey]: keyof MessageParams[K] extends never
    ? { readonly key: K; readonly values?: never }
    : { readonly key: K; readonly values: MessageParams[K] }
}[MessageKey];
